#include <iostream>
using namespace std;

int main() {
    int fish[3] = {0, 0, 0};
    cin >> fish[0] >> fish[1] >> fish[2];

    int* p = fish;
    cout << p[2] << endl;
    cout << *(p + 1) << endl;
    cout << *p << endl;
    return 0;
}
